package com.quickmanager.debug;

import org.springframework.security.crypto.bcrypt.BCrypt;

public class GenerateHashes {
    public static void main(String[] args) {
        String[][] data = new String[][]{
            {"admin", "Admin@123"},
            {"ketoan.lan", "Lan@123"},
            {"thukho.bao", "Bao@123"},
            {"thungan.ha", "Ha@123"},
            {"thungan.nam", "Nam@123"},
            {"banhang.anh", "Anh@123"},
            {"banhang.tung", "Tung@123"},
            {"cskh.dung", "Dung@123"},
            {"giamsat.huy", "Huy@123"},
            {"linh.old", "Linh@123"}
        };

        for (String[] u : data) {
            String user = u[0];
            String pass = u[1];
            String hash = BCrypt.hashpw(pass, BCrypt.gensalt());
            System.out.println(user + ":" + hash);
        }
    }
}
